(4112891, 590743, 41047, '<td valign="top">beautiful.</td>', 'beautiful.', '2007-09-24 16:52:36.000000', NULL, 1),
(4113051, 590835, 52713, '<td valign="top">I like this idea a lot. The technicals are good too. I wish there were something more in the way of a background or foundation.</td>', 'I like this idea a lot. The technicals are good too. I wish there were something more in the way of a background or foundation.', '2007-09-24 18:50:28.000000', NULL, 1),
