(4113056, 590222, 52713, '<td valign="top">one of my top picks. Nicely done, even if the gyroscope doesn''t have any real context to the rest of the image.</td>', 'one of my top picks. Nicely done, even if the gyroscope doesn''t have any real context to the rest of the image.', '2007-09-24 18:51:55.000000', NULL, 1),
(4113058, 589378, 52713, '<td valign="top">love the light painting technique! - no vote</td>', 'love the light painting technique! - no vote', '2007-09-24 18:52:49.000000', NULL, 1),
