(4113070, 590248, 52713, '<td valign="top">nicely done.</td>', 'nicely done.', '2007-09-24 18:57:32.000000', NULL, 1),
(4113072, 590465, 52713, '<td valign="top">gret idea, lack of sharpness is probably going to cost you some points.</td>', 'gret idea, lack of sharpness is probably going to cost you some points.', '2007-09-24 18:58:33.000000', NULL, 1),
(4113074, 590470, 52713, '<td valign="top">great processing and comp. Lighting is awesome too. Something doesn''t look right about the pouring liquid.</td>', 'great processing and comp. Lighting is awesome too. Something doesn''t look right about the pouring liquid.', '2007-09-24 18:59:33.000000', NULL, 1),
