(4113221, 589354, 37444, '<td valign="top">cute - 8</td>', 'cute - 8', '2007-09-24 20:36:28.000000', NULL, 1),
(4113222, 588154, 66952, '<td valign="top">One of the best ideas in the challenge, and well executed. The only problem I see with it is in the small DPC format, the multiple frames take up so much space that the "still life" in the middle is really tiny. Still, one of my top scores.</td>', 'One of the best ideas in the challenge, and well executed. The only problem I see with it is in the small DPC format, the multiple frames take up so much space that the "still life" in the middle is really tiny. Still, one of my top scores.', '2007-09-24 20:36:30.000000', NULL, 1),
(4113225, 590743, 37444, '<td valign="top">very nice image, but I''d prefer the window to have been farther to the left. - 8</td>', 'very nice image, but I''d prefer the window to have been farther to the left. - 8', '2007-09-24 20:37:23.000000', NULL, 1),
(4113226, 590277, 37444, '<td valign="top">nicely done - 8</td>', 'nicely done - 8', '2007-09-24 20:38:15.000000', NULL, 1),
