(4113243, 590723, 66952, '<td valign="top">Solid technicals, good concept. One of the better ones in the challenge.</td>', 'Solid technicals, good concept. One of the better ones in the challenge.', '2007-09-24 20:46:05.000000', NULL, 1),
(4113244, 589764, 66952, '<td valign="top">Very funny! A great take on the challenge topic.</td>', 'Very funny! A great take on the challenge topic.', '2007-09-24 20:46:53.000000', NULL, 1),
(4113245, 590595, 66952, '<td valign="top">An elegant and delicately lit still life.</td>', 'An elegant and delicately lit still life.', '2007-09-24 20:47:48.000000', NULL, 1),
(4113256, 589937, 59629, '<td valign="top">I really like this image...very nicely done.</td>', 'I really like this image...very nicely done.', '2007-09-24 21:08:01.000000', NULL, 1),
