(4113650, 588402, 48697, '<td valign="top">nice candid street shot1</td>', 'nice candid street shot1', '2007-09-25 00:09:48.000000', NULL, 1),
(4113653, 589875, 41337, '<td valign="top">Just my opinion of course but this is a landscape shot with motion not still life with motion.</td>', 'Just my opinion of course but this is a landscape shot with motion not still life with motion.', '2007-09-25 00:10:20.000000', NULL, 1),
(4113662, 590277, 48697, '<td valign="top">very nice! Love the composition and the lighting in this shot!</td>', 'very nice! Love the composition and the lighting in this shot!', '2007-09-25 00:13:14.000000', NULL, 1),
(4113680, 589330, 41337, '<td valign="top">I''m sorry but I don''t see still life or motion depicted here. I can probably give you a pass on the motion part if I am to assume that water by it''s nature is always moving. However, if I do that then that ship by it''s nature isn''t still and is in fact also moving as is the sun so I am left to wonder what is still. One could argue that the mood "feels" still but you are so far away from what still life is that I have a hard time giving you credit for this shot. Although I will say it''s growing on me a little.</td>', 'I''m sorry but I don''t see still life or motion depicted here. I can probably give you a pass on the motion part if I am to assume that water by it''s nature is always moving. However, if I do that then that ship by it''s nature isn''t still and is in fact also moving as is the sun so I am left to wonder what is still. One could argue that the mood "feels" still but you are so far away from what still life is that I have a hard time giving you credit for this shot. Although I will say it''s growing on me a little.', '2007-09-25 00:17:34.000000', NULL, 1),
(4113681, 588424, 48697, '<td valign="top">cool smoke shot, well composed and nice colors. I do feel that this does not meet the challenge discription though.</td>', 'cool smoke shot, well composed and nice colors. I do feel that this does not meet the challenge discription though.', '2007-09-25 00:17:35.000000', NULL, 1),
