(4114573, 590837, 68035, '<td valign="top">Very good, the sort of image that took me a second to get, but is all the better for it nice composition excellent idea, humour and good execution<br/> <br/>8</td>', 'Very good, the sort of image that took me a second to get, but is all the better for it nice composition excellent idea, humour and good execution 8', '2007-09-25 13:43:59.000000', NULL, 1),
(4114587, 590277, 66952, '<td valign="top">An interesting, graphic shot. I like the composition and high contrast treatment. Not sure if it counts as "still life" or not, since the only thing that''s not moving is the background.</td>', 'An interesting, graphic shot. I like the composition and high contrast treatment. Not sure if it counts as "still life" or not, since the only thing that''s not moving is the background.', '2007-09-25 13:55:32.000000', NULL, 1),
(4114631, 588424, 66952, '<td valign="top">Nice job on the smoke. Very delicate.</td>', 'Nice job on the smoke. Very delicate.', '2007-09-25 14:26:46.000000', NULL, 1),
(4114692, 589920, 82817, '<td valign="top">The colors of the flower are wonderful. I am distracted by the water splashing on the lower left, at least I think it''s water. Might have worked better with a tighter cropping.</td>', 'The colors of the flower are wonderful. I am distracted by the water splashing on the lower left, at least I think it''s water. Might have worked better with a tighter cropping.', '2007-09-25 14:54:50.000000', NULL, 1),
(4114699, 590888, 82817, '<td valign="top">I love this with the movement and still life but the colors are to me a bit too much the same. Probably the brick background is what pulls my attention away. Great timing of the shot. Hope you didn''t have to waste too much wine.</td>', 'I love this with the movement and still life but the colors are to me a bit too much the same. Probably the brick background is what pulls my attention away. Great timing of the shot. Hope you didn''t have to waste too much wine.', '2007-09-25 14:57:24.000000', NULL, 1),
(4114703, 590379, 82817, '<td valign="top">The black object in the lower right is calling for attention.</td>', 'The black object in the lower right is calling for attention.', '2007-09-25 14:59:00.000000', NULL, 1),
(4114709, 590826, 82817, '<td valign="top">Nice! The sugar is a touch blown out but I love this.</td>', 'Nice! The sugar is a touch blown out but I love this.', '2007-09-25 15:00:03.000000', NULL, 1),
(4114715, 590835, 66952, '<td valign="top">Great idea! The lighting may be a little hot, especially at the top. The blobs of milk are blown out and lose their shape. Down lower, next to the cereal, there are still shadows and shape to the milk.</td>', 'Great idea! The lighting may be a little hot, especially at the top. The blobs of milk are blown out and lose their shape. Down lower, next to the cereal, there are still shadows and shape to the milk.', '2007-09-25 15:01:31.000000', NULL, 1),
(4114716, 590582, 82817, '<td valign="top">The left side really holds my interest but the right is not working for me.</td>', 'The left side really holds my interest but the right is not working for me.', '2007-09-25 15:01:44.000000', NULL, 1),
(4114722, 588487, 82817, '<td valign="top">Great timing. Color seems a little lifeless.</td>', 'Great timing. Color seems a little lifeless.', '2007-09-25 15:02:58.000000', NULL, 1),
(4114728, 590776, 82817, '<td valign="top">While on a photo shoot an apple was shot through the core. Police suspect foul play. Thought provoking shot. Thanks.</td>', 'While on a photo shoot an apple was shot through the core. Police suspect foul play. Thought provoking shot. Thanks.', '2007-09-25 15:08:14.000000', NULL, 1),
(4114732, 590870, 82817, '<td valign="top">Close but not quite there. Great idea and hard to capture.</td>', 'Close but not quite there. Great idea and hard to capture.', '2007-09-25 15:09:31.000000', NULL, 1),
(4114735, 590470, 82817, '<td valign="top">Lovely still life. Is there a hole in the glass or how is the wine moving through the glass?</td>', 'Lovely still life. Is there a hole in the glass or how is the wine moving through the glass?', '2007-09-25 15:11:38.000000', NULL, 1),
(4114738, 590904, 82817, '<td valign="top">Beautiful flowers.</td>', 'Beautiful flowers.', '2007-09-25 15:13:06.000000', NULL, 1),
(4114740, 589745, 82817, '<td valign="top">Colors are incredible but the movement is a bit hard to detect. I think the water is a bit slow running or.....</td>', 'Colors are incredible but the movement is a bit hard to detect. I think the water is a bit slow running or.....', '2007-09-25 15:14:24.000000', NULL, 1),
(4114743, 590884, 67152, '<td valign="top">real nice composition, colors and stop action on the pouring/ spilling of the liquid</td>', 'real nice composition, colors and stop action on the pouring/ spilling of the liquid', '2007-09-25 15:15:52.000000', NULL, 1),
(4114746, 590706, 82817, '<td valign="top">The still life is uninteresting, IMO. Love the movement of the green leaf. Nice textures.</td>', 'The still life is uninteresting, IMO. Love the movement of the green leaf. Nice textures.', '2007-09-25 15:16:20.000000', NULL, 1),
(4114751, 590248, 67152, '<td valign="top">an excellent image with a great simple story - the composition is spot on and the background makes the image</td>', 'an excellent image with a great simple story - the composition is spot on and the background makes the image', '2007-09-25 15:17:25.000000', NULL, 1),
(4114754, 590722, 67152, '<td valign="top">good light, well captured</td>', 'good light, well captured', '2007-09-25 15:17:57.000000', NULL, 1),
(4114760, 590047, 82817, '<td valign="top">The white light is screaming for attention. The green yellow and blue are great.</td>', 'The white light is screaming for attention. The green yellow and blue are great.', '2007-09-25 15:19:00.000000', NULL, 1),
(4114769, 589774, 82817, '<td valign="top">Wonderful soft movement. Even the picture frame was moved from the painter within. Great idea and execution.</td>', 'Wonderful soft movement. Even the picture frame was moved from the painter within. Great idea and execution.', '2007-09-25 15:20:55.000000', NULL, 1),
(4114774, 590485, 67152, '<td valign="top">very creative job - love the use of butterflies as the in-motion object</td>', 'very creative job - love the use of butterflies as the in-motion object', '2007-09-25 15:22:26.000000', NULL, 1),
(4114777, 590724, 82817, '<td valign="top">The bowl on the right is a bit bright but it does draw the viewer in to the whisk on the Kitchen Aid.</td>', 'The bowl on the right is a bit bright but it does draw the viewer in to the whisk on the Kitchen Aid.', '2007-09-25 15:22:57.000000', NULL, 1),
