(4114781, 590294, 82817, '<td valign="top">Great fall colors and wonderful leaf movement.</td>', 'Great fall colors and wonderful leaf movement.', '2007-09-25 15:23:50.000000', NULL, 1),
(4114784, 590757, 82817, '<td valign="top">Implied movement. Love it.</td>', 'Implied movement. Love it.', '2007-09-25 15:24:57.000000', NULL, 1),
(4114785, 590722, 82817, '<td valign="top">Beautiful! And yummy!</td>', 'Beautiful! And yummy!', '2007-09-25 15:25:48.000000', NULL, 1),
(4114786, 590732, 67152, '<td valign="top">very nice simple and effective image - the choice of b/w is good.  How many oreos did you get to eat?</td>', 'very nice simple and effective image - the choice of b/w is good.  How many oreos did you get to eat?', '2007-09-25 15:25:51.000000', NULL, 1),
