(4115042, 589542, 75898, '<td valign="top">Nice choice of material for the bottom.  IMO, the reflection adds just as much (if not more) movement than the clock.  Well done.</td>', 'Nice choice of material for the bottom.  IMO, the reflection adds just as much (if not more) movement than the clock.  Well done.', '2007-09-25 17:43:41.000000', NULL, 1),
(4115080, 589884, 66952, '<td valign="top">An excellent idea! It would work better if the flowers and glass were a bit sharper, but still gets a 6 from me.</td>', 'An excellent idea! It would work better if the flowers and glass were a bit sharper, but still gets a 6 from me.', '2007-09-25 18:03:46.000000', NULL, 1),
