(4115196, 590884, 66952, '<td valign="top">Fun! I like the contrast between the glasses in the back, sitting there quietly, with the action in the front.</td>', 'Fun! I like the contrast between the glasses in the back, sitting there quietly, with the action in the front.', '2007-09-25 18:55:33.000000', NULL, 1),
(4115283, 590757, 67152, '<td valign="top">very cool image - love the colors and composition - but the background noise is distracting.  back for a bump to 7.</td>', 'very cool image - love the colors and composition - but the background noise is distracting.  back for a bump to 7.', '2007-09-25 19:56:43.000000', NULL, 1),
(4115348, 590807, 68035, '<td valign="top">Love the idea and the composition, meets the challenge very well, my only (very) minor comment would be that the desktop seems somehow muted compared to the rest of the image.  Still an excellent 8 though</td>', 'Love the idea and the composition, meets the challenge very well, my only (very) minor comment would be that the desktop seems somehow muted compared to the rest of the image.  Still an excellent 8 though', '2007-09-25 20:16:33.000000', NULL, 1),
(4115352, 590888, 68035, '<td valign="top">Great shot and fantastic capture of the action, which goes very well with the ''still'' element of the image.  Bumping to 9.</td>', 'Great shot and fantastic capture of the action, which goes very well with the ''still'' element of the image.  Bumping to 9.', '2007-09-25 20:17:49.000000', NULL, 1),
(4115355, 590651, 68035, '<td valign="top">Simple beautiful and very effective, it meets the challenge and the black and white conversion is excellent - 8</td>', 'Simple beautiful and very effective, it meets the challenge and the black and white conversion is excellent - 8', '2007-09-25 20:18:28.000000', NULL, 1),
(4115360, 590884, 68035, '<td valign="top">Excellent concept wonderfully delivered, the over exposed background is great.  An 8 from me and I feel that this could well be a ribbon winner</td>', 'Excellent concept wonderfully delivered, the over exposed background is great.  An 8 from me and I feel that this could well be a ribbon winner', '2007-09-25 20:19:41.000000', NULL, 1),
