(4122286, 590604, 83313, '<td valign="top">The flowers on the pedestal are clearly the subject, but the heavy backlighting gives them shadows that tries to send my gaze to the fountain in the background instead.</td>', 'The flowers on the pedestal are clearly the subject, but the heavy backlighting gives them shadows that tries to send my gaze to the fountain in the background instead.', '2007-09-28 11:48:02.000000', NULL, 1),
(4122298, 590888, 83313, '<td valign="top">The motion of the breaking glass seems lost a bit in the pattern of the grapes, the colors are so similar. Otherwise, quite nice.</td>', 'The motion of the breaking glass seems lost a bit in the pattern of the grapes, the colors are so similar. Otherwise, quite nice.', '2007-09-28 11:55:30.000000', NULL, 1),
(4122301, 590835, 83313, '<td valign="top">Not the usual still life subject. Good thinking on this one.</td>', 'Not the usual still life subject. Good thinking on this one.', '2007-09-28 11:57:03.000000', NULL, 1),
