(4122564, 590410, 43774, '<td valign="top">Cute idea! The light swirls are a bitt too bright and contrasty for my tastes.</td>', 'Cute idea! The light swirls are a bitt too bright and contrasty for my tastes.', '2007-09-28 14:38:35.000000', NULL, 1),
(4122565, 590888, 43774, '<td valign="top">Very good idea. Unfortunately the glass is lost in the busy background of the grapes and it''s hard to see the breaking glass and spilling wine. Maybe a different positioning of it?</td>', 'Very good idea. Unfortunately the glass is lost in the busy background of the grapes and it''s hard to see the breaking glass and spilling wine. Maybe a different positioning of it?', '2007-09-28 14:39:35.000000', NULL, 1),
