(4123363, 589774, 41337, '<td valign="top">Very unusual shot. The lighting is a little bland but the idea is good.</td>', 'Very unusual shot. The lighting is a little bland but the idea is good.', '2007-09-28 21:30:15.000000', NULL, 1),
(4123369, 590492, 41337, '<td valign="top">The original had a very clean/classy look. Your lighting is very good and compliments that very well. The water explosion on the other hand feels a little too messy when you have the original in mind. Perhaps capturing the explosion before it leaves the mess on the table would have been best. Anyway, just a thought.</td>', 'The original had a very clean/classy look. Your lighting is very good and compliments that very well. The water explosion on the other hand feels a little too messy when you have the original in mind. Perhaps capturing the explosion before it leaves the mess on the table would have been best. Anyway, just a thought.', '2007-09-28 21:39:51.000000', NULL, 1),
(4123370, 590341, 41337, '<td valign="top">More of a clever play on words than still life but interesting nonetheless.</td>', 'More of a clever play on words than still life but interesting nonetheless.', '2007-09-28 21:39:58.000000', NULL, 1),
(4123371, 590743, 41337, '<td valign="top">Not what I''d normally consider still life + motion but you managed to capture the essence of the words nonetheless.</td>', 'Not what I''d normally consider still life + motion but you managed to capture the essence of the words nonetheless.', '2007-09-28 21:40:05.000000', NULL, 1),
