(4123404, 590727, 84526, '<td valign="top">Lovely shot. Put a smile on my face</td>', 'Lovely shot. Put a smile on my face', '2007-09-28 21:54:33.000000', NULL, 1),
(4123405, 590706, 41337, '<td valign="top">I like the textures and the lighting is decent. However, the motion feels a bit forced,IMO. It doesn''t look real enough if I am to believe it''s a gentle breeze causing the leaf to move. I suppose it could be coming from below through that opening but the natural tendency to feel breeze would be from the left or right not from below. It would have been easier to communicate the breeze if the leaf was attached to the branch and was then waving in the wind.</td>', 'I like the textures and the lighting is decent. However, the motion feels a bit forced,IMO. It doesn''t look real enough if I am to believe it''s a gentle breeze causing the leaf to move. I suppose it could be coming from below through that opening but the natural tendency to feel breeze would be from the left or right not from below. It would have been easier to communicate the breeze if the leaf was attached to the branch and was then waving in the wind.', '2007-09-28 21:57:20.000000', NULL, 1),
(4123406, 590248, 41098, '<td valign="top">One of my top picks - great creativity, crisp focus and overall GREAT SHOT</td>', 'One of my top picks - great creativity, crisp focus and overall GREAT SHOT', '2007-09-28 21:57:47.000000', NULL, 1),
