(4125798, 589392, 70000, '<td valign="top">oh my gosh oh my gosh!!! your lighting is awesome and i LOVEEE that you turned the picture upsidedown. It completely changes the perspective and makes it different from all the other collored water in a glass shots there are out there. clever title as well</td>', 'oh my gosh oh my gosh!!! your lighting is awesome and i LOVEEE that you turned the picture upsidedown. It completely changes the perspective and makes it different from all the other collored water in a glass shots there are out there. clever title as well', '2007-09-30 11:13:18.000000', NULL, 1),
(4125800, 589774, 70000, '<td valign="top">very well composed and very clever, however the lighting seems off. light coming from below caused dark shaddows and also makes the lighting on the hands in the photo very dull</td>', 'very well composed and very clever, however the lighting seems off. light coming from below caused dark shaddows and also makes the lighting on the hands in the photo very dull', '2007-09-30 11:14:04.000000', NULL, 1),
(4125804, 590862, 70000, '<td valign="top">woah ok second bullet shot. did you actually shot an apple? this had to have taken AGES to do...WONDERFULLY composed and true luck that the bullet is right in the perfect shot to really add to the composition. great job!</td>', 'woah ok second bullet shot. did you actually shot an apple? this had to have taken AGES to do...WONDERFULLY composed and true luck that the bullet is right in the perfect shot to really add to the composition. great job!', '2007-09-30 11:15:01.000000', NULL, 1),
